    {
      "design": "r2A",
      "good": "Destination names are easy to scan, delivery windows stay intact, and the Delivery group is clear. The longest destination wraps naturally within a row already made tall by its conditions.",
      "problems": "The Visayas condition ends with the isolated word “point.”, and most conditions occupy four lines.",
      "cause": "The 508px Conditions column falls just short of fitting some text into more balanced lines; the 126px Destination column uses space that could help the conditions."
    },
    {
      "design": "r2B",
      "good": "The wider Conditions column gives the first three rows three-line conditions, improving the table’s rhythm. Windows remain intact and the grouped header is clear.",
      "problems": "Greater Luzon wraps even though it is a relatively short row identifier. The last two conditions still take four lines.",
      "cause": "The 115px Destination column leaves too little text width for Greater Luzon; its space is assigned to the 519px Conditions column."
    },
    {
      "design": "r2C",
      "good": "Every destination stays on one line, making the row identifiers particularly easy to scan. Windows and headers also remain intact.",
      "problems": "All five conditions take four lines, making every row tall and leaving considerable unused space beneath most destination names.",
      "cause": "The 166px Destination column accommodates the longest name on one line, but reduces Conditions to 468px."
    }
  ],
  "done": false,
