    {
      "name": "balanced",
      "widths": [121, 85, 513],
      "change": "Test a middle ground between r2A and r2B: give Destination enough room to keep Greater Luzon together while returning a few pixels to Conditions. Remote island areas can wrap naturally."
    },
    {
      "name": "conditions-first",
      "widths": [112, 85, 522],
